// DecodeTemplateUpdatedEvent decodes a "TemplateUpdated(bytes32,uint64)" log.
func (c *IDiesisErc20FactoryBinding) DecodeTemplateUpdatedEvent(log types.Log) (out IDiesisErc20FactoryTemplateUpdatedEvent, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI event: %v", failure)
		}
	}()
	definition, err := c.event("TemplateUpdated(bytes32,uint64)")
	if err != nil {
		return out, err
	}
	if len(log.Topics) == 0 || log.Topics[0] != definition.ID {
		return out, fmt.Errorf("event signature mismatch for %s", "TemplateUpdated(bytes32,uint64)")
	}
	if len(log.Topics) != 1 {
		return out, fmt.Errorf("event topic count mismatch for %s", "TemplateUpdated(bytes32,uint64)")
	}
	if len(definition.Inputs.NonIndexed()) > 0 {
		values, err := definition.Inputs.NonIndexed().Unpack(log.Data)
		if err != nil {
			return out, err
		}
		if len(values) != 2 {
			return out, fmt.Errorf("event value count mismatch")
		}
		out.NewBytecodeHash = *abi.ConvertType(values[0], new([32]byte)).(*[32]byte)
		out.UnlockBlock = *abi.ConvertType(values[1], new(uint64)).(*uint64)
	} else if len(log.Data) != 0 {
		return out, fmt.Errorf("unexpected event data")
	}
	var indexed abi.Arguments
	var indexedTopics []common.Hash
	if err := abi.ParseTopics(&out, indexed, indexedTopics); err != nil {
		return out, err
	}
	return out, nil
}

// FilterTemplateUpdated retrieves and decodes "TemplateUpdated(bytes32,uint64)" logs. Indexed filters follow ABI order.
func (c *IDiesisErc20FactoryBinding) FilterTemplateUpdated(ctx context.Context, from, to *big.Int, indexed ...[]any) ([]IDiesisErc20FactoryTemplateUpdatedEvent, error) {
	if c.backend == nil {
		return nil, fmt.Errorf("IDiesisErc20FactoryBinding has no backend")
	}
	definition, err := c.event("TemplateUpdated(bytes32,uint64)")
	if err != nil {
		return nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, fmt.Errorf("too many indexed filters for %s", "TemplateUpdated(bytes32,uint64)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, err
	}
	logs, err := c.backend.FilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics, FromBlock: from, ToBlock: to})
	if err != nil {
		return nil, err
	}
	out := make([]IDiesisErc20FactoryTemplateUpdatedEvent, 0, len(logs))
	for _, log := range logs {
		decoded, err := c.DecodeTemplateUpdatedEvent(log)
		if err != nil {
			return nil, err
		}
		out = append(out, decoded)
	}
	return out, nil
}

