// DecodeDuplicateDeploymentError decodes a "DuplicateDeployment()" revert payload, including its selector.
func (c *IDiesisErc20FactoryBinding) DecodeDuplicateDeploymentError(raw []byte) (out IDiesisErc20FactoryDuplicateDeploymentError, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI error: %v", failure)
		}
	}()
	definition, err := c.customError("DuplicateDeployment()")
	if err != nil {
		return out, err
	}
	if len(raw) < 4 || !bytes.Equal(raw[:4], definition.ID[:4]) {
		return out, fmt.Errorf("error selector mismatch for %s", "DuplicateDeployment()")
	}
	values, err := definition.Inputs.Unpack(raw[4:])
	if err != nil {
		return out, err
	}
	if len(values) != 0 {
		return out, fmt.Errorf("error value count mismatch")
	}
	return out, nil
}

