// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisErc20FactoryBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("DuplicateDeployment()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeDuplicateDeploymentError(raw)
	}
	if definition, err := c.customError("FactoryCallFailed()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeFactoryCallFailedError(raw)
	}
	if definition, err := c.customError("InvalidDecimals()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidDecimalsError(raw)
	}
	if definition, err := c.customError("InvalidSupply()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidSupplyError(raw)
	}
	if definition, err := c.customError("InvalidSymbolLength()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidSymbolLengthError(raw)
	}
	if definition, err := c.customError("TemplateUpdateLocked()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeTemplateUpdateLockedError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
